/**
 * Shared message-body normalizer — keep in sync with lib/message-body.ts.
 * Used at inbound ingestion and on read for customer reply text.
 */

const HTML_ENTITIES = {
  "&nbsp;": " ",
  "&amp;": "&",
  "&lt;": "<",
  "&gt;": ">",
  "&quot;": '"',
  "&#39;": "'",
  "&apos;": "'",
};

function decodeHtmlEntities(s) {
  return String(s).replace(/&(?:nbsp|amp|lt|gt|quot|apos|#39);/gi, (m) => HTML_ENTITIES[m.toLowerCase()] ?? m);
}

function stripHtml(s) {
  let out = String(s);
  out = out.replace(/<br\s*\/?>/gi, "\n");
  out = out.replace(/<\/p>/gi, "\n\n");
  out = out.replace(/<[^>]+>/g, "");
  return decodeHtmlEntities(out);
}

function collapseWhitespace(s) {
  return String(s)
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n[ \t]+/g, "\n")
    .trim();
}

function stripJsonArtifacts(s) {
  let out = String(s).trim();
  out = out.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "");
  if (!out.startsWith("{")) return out;
  try {
    const parsed = JSON.parse(out);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      if (typeof parsed.classification === "string") return "";
      for (const key of ["replyText", "text", "body", "message", "emailBody", "waBody", "content"]) {
        if (typeof parsed[key] === "string" && parsed[key].trim()) return parsed[key].trim();
      }
    }
  } catch {
    /* not JSON */
  }
  return out;
}

const EMAIL_QUOTE_PATTERNS = [
  /\n-{2,}\s*original message\s*-{2,}/i,
  /\n-{5,}\s*forwarded message\s*-{5,}/i,
  /\nfrom:\s*.+\n(?:sent|date):\s*.+/i,
  /\non\s.+wrote:\s*\n/i,
  /\n_{5,}\n/,
];

function trimEmailReply(s) {
  let out = String(s);
  let cutAt = out.length;
  for (const pat of EMAIL_QUOTE_PATTERNS) {
    const m = pat.exec(out);
    if (m && m.index < cutAt) cutAt = m.index;
  }
  out = out.slice(0, cutAt);
  const lines = out.split("\n");
  const kept = [];
  for (const line of lines) {
    if (/^>/.test(line.trim())) break;
    kept.push(line);
  }
  return collapseWhitespace(kept.join("\n"));
}

function objectToPlainText(obj) {
  if (obj == null) return "";
  if (typeof obj === "string") return obj.trim();
  if (typeof obj === "number" || typeof obj === "boolean") return String(obj);
  if (Array.isArray(obj)) {
    const parts = obj.map(objectToPlainText).filter(Boolean);
    return parts.join("\n").trim();
  }
  if (typeof obj === "object") {
    for (const key of ["text", "body", "Body", "content", "message", "replyText", "bodyPlain"]) {
      if (typeof obj[key] === "string" && obj[key].trim()) return obj[key].trim();
    }
    const vals = Object.values(obj)
      .map((v) => (typeof v === "string" ? v.trim() : ""))
      .filter(Boolean);
    if (vals.length === 1) return vals[0];
    if (vals.length > 1) return vals.join(" ").trim();
  }
  return "";
}

function coercePlainText(raw) {
  if (raw == null || raw === "") return "";
  if (typeof raw === "string") return raw.trim();
  const fromObj = objectToPlainText(raw);
  if (fromObj) return fromObj;
  return "";
}

/**
 * @param {unknown} raw
 * @param {{ channel?: 'email' | 'whatsapp' | 'manual' }} [opts]
 * @returns {string}
 */
function normalizeMessageBody(raw, opts) {
  const channel = opts && opts.channel ? opts.channel : "manual";
  let text = coercePlainText(raw);
  if (!text) return "";
  text = stripJsonArtifacts(text);
  if (channel === "email") {
    text = stripHtml(text);
    text = trimEmailReply(text);
  }
  return collapseWhitespace(text);
}

const b = $json.body || $json;
const raw = b.bodyPlain ?? b.body ?? '';
const bodyPlain = normalizeMessageBody(raw, { channel: 'email' }).slice(0, 2000);
return {
  json: {
    messageId: String(b.messageId || b.id || ('EM' + Date.now())),
    fromEmail: String(b.fromEmail || b.from || ''),
    subject: String(b.subject || ''),
    bodyPlain,
    receivedAt: String(b.receivedAt || new Date().toISOString()),
    now: new Date().toISOString(),
  },
};

const meta = $('Parse email').item.json;
const SELF = 'piyushtater158@gmail.com';
function normEmail(raw) {
  const s = String(raw || '').trim().toLowerCase();
  const m = s.match(/<([^>]+)>/);
  return (m ? m[1] : s).trim();
}
const from = normEmail(meta.fromEmail);
if (!from || from === normEmail(SELF)) {
  return [{ json: { ...meta, matchCount: 0, attachInvoiceId: '', matchReason: 'ignored_self', logStatus: 'pending' } }];
}
const subjectInv = (meta.subject || '').match(/INV-\d+/i);
const subjectId = subjectInv ? subjectInv[0].toUpperCase() : '';
const rows = $input.all().map(({ json: r }) => ({
  id: String(r.id || ''),
  email: normEmail(r.email),
  stage: String(r.stage || '').toLowerCase(),
  emailSentAt: String(r.emailSentAt || '').trim(),
}));
const openEligible = (r) =>
  (r.stage === 'sent' || r.stage === 'replied') &&
  (String(r.emailSentAt || '').trim() !== '' || r.stage === 'sent');
const matches = rows.filter((r) => r.email && r.email === from && openEligible(r));
let attachInvoiceId = '';
let matchReason = 'unmatched';
let matchCount = 0;
let matchIds = [];
if (matches.length === 1) {
  matchCount = 1;
  matchIds = [matches[0].id];
  if (subjectId && subjectId !== matches[0].id.toUpperCase()) {
    matchReason = 'ambiguous_subject_mismatch';
  } else {
    attachInvoiceId = matches[0].id;
    matchReason = 'attached';
  }
} else if (matches.length > 1) {
  matchIds = matches.map((m) => m.id);
  matchCount = matches.length;
  if (subjectId) {
    const subjectMatches = matches.filter((m) => m.id.toUpperCase() === subjectId);
    if (subjectMatches.length === 1) {
      attachInvoiceId = subjectMatches[0].id;
      matchReason = 'attached';
      matchCount = 1;
      matchIds = [subjectMatches[0].id];
    } else {
      matchReason = 'ambiguous_multiple';
    }
  } else {
    matchReason = 'ambiguous_multiple';
  }
}
return [{ json: {
  ...meta,
  matchIds,
  matchCount,
  attachInvoiceId,
  matchReason,
  logStatus: attachInvoiceId ? 'attached' : 'pending',
  attachedInvoiceId: attachInvoiceId,
  body: meta.bodyPlain,
  kind: 'reply',
  from: meta.fromEmail,
  sid: meta.messageId,
} }];
